class BillingClient
  def initialize(base_url:, token:) = (@base, @token = base_url, token)
  def create_invoice(cmd)
    conn.post('/invoices') { |r| r.body = cmd }
  rescue Faraday::Error => e
    raise BillingUnavailable, e.message           # translate, keep the cause
  end
  def conn = (@conn ||= Faraday.new(@base) { |f|   # memoized delegate
    f.request :authorization, 'Bearer', @token
    f.response :raise_error
    f.adapter :net_http_persistent
  })
end
